fun decodeBlueprintGroupName(json: JsonValue, path: String): BlueprintGroupName =
    json.str(path)

/**
 * Reads one value: {"$state": name} (local state) or {"$data": name} (host data, read-only).
 * Exactly one key; checked by the validator.
 */
data class BlueprintBinding(
    val state: BlueprintStateName? = null,
    val data: BlueprintDataName? = null,
) {
    companion object {
        private val FIELDS = setOf("\$state", "\$data")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintBinding {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintBinding(
                state = fields["\$state"]?.let { decodeBlueprintStateName(it, "$path.\$state") },
                data = fields["\$data"]?.let { decodeBlueprintDataName(it, "$path.\$data") },
            )
        }
    }
}

/**
 * One typed, bounded variable (mirrors `@texuli/player` parseStateDeclarations; list and workflow
 * are new). Per-type fields and initial values are checked by the validator.
 */
