        fun decode(json: JsonValue, path: String = "\$"): BlueprintStateDeclaration {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintStateDeclaration(
                type = BlueprintStateDeclarationType.decode(fields.required("type", path), "$path.type"),
                initial = fields["initial"]?.let { it },
                min = fields["min"]?.let { it.double("$path.min") },
                max = fields["max"]?.let { it.double("$path.max") },
                values = fields["values"]?.let { ("$path.values").let { p -> it.arrValues(p).mapIndexed { i, item -> item.str("$p[$i]") } } },
                maxLength = fields["maxLength"]?.let { it.long("$path.maxLength") },
                maxItems = fields["maxItems"]?.let { it.long("$path.maxItems") },
                source = fields["source"]?.let { decodeBlueprintDataName(it, "$path.source") },
            )
        }
    }
}

