/**
 * One closed action. Per-op fields are checked by the validator (setState: state +
 * value|fromEvent; toggleState: state; moveItem: from, item, to?, index?; flowGo: event; emit:
 * intent, values?; submit: none).
 */
data class BlueprintAction(
    val op: BlueprintActionOp,
    val state: BlueprintStateName? = null,
    val value: JsonValue? = null,
    val fromEvent: BlueprintActionFromEvent? = null,
    val from: BlueprintStateName? = null,
    val to: BlueprintStateName? = null,
    val item: BlueprintItemKey? = null,
    val index: Long? = null,
    val event: BlueprintFlowName? = null,
    val intent: BlueprintIntentName? = null,
    val values: Map<String, JsonValue>? = null,
) {
    companion object {
        private val FIELDS = setOf("op", "state", "value", "fromEvent", "from", "to", "item", "index", "event", "intent", "values")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintAction {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintAction(
                op = BlueprintActionOp.decode(fields.required("op", path), "$path.op"),
                state = fields["state"]?.let { decodeBlueprintStateName(it, "$path.state") },
                value = fields["value"]?.let { it },
                fromEvent = fields["fromEvent"]?.let { BlueprintActionFromEvent.decode(it, "$path.fromEvent") },
                from = fields["from"]?.let { decodeBlueprintStateName(it, "$path.from") },
                to = fields["to"]?.let { decodeBlueprintStateName(it, "$path.to") },
                item = fields["item"]?.let { decodeBlueprintItemKey(it, "$path.item") },
                index = fields["index"]?.let { it.long("$path.index") },
                event = fields["event"]?.let { decodeBlueprintFlowName(it, "$path.event") },
                intent = fields["intent"]?.let { decodeBlueprintIntentName(it, "$path.intent") },
                values = fields["values"]?.let { ("$path.values").let { p -> it.obj(p).mapValues { (k, item) -> item } } },
            )
        }
    }
}

/**
 * Event → actions run in order. Keys must be events the component declares (catalog events).
 */
typealias BlueprintEventMap = Map<String, List<BlueprintAction>>

fun decodeBlueprintEventMap(json: JsonValue, path: String): BlueprintEventMap =
    (path).let { p -> json.obj(p).mapValues { (k, item) -> ("$p.$k").let { p -> item.arrValues(p).mapIndexed { i, item -> BlueprintAction.decode(item, "$p[$i]") } } } }

/**
 * Drag as data: the container's items are the bound list; a drop or keyboard move runs the closed
 * moveItem reducer. Containers sharing a group exchange items when accepts allows.
 */
data class BlueprintReorder(
    val bind: BlueprintBinding,
    val axis: BlueprintReorderAxis? = null,
    val group: BlueprintGroupName? = null,
