                axis = fields["axis"]?.let { BlueprintReorderAxis.decode(it, "$path.axis") },
                group = fields["group"]?.let { decodeBlueprintGroupName(it, "$path.group") },
                accepts = fields["accepts"]?.let { ("$path.accepts").let { p -> it.arrValues(p).mapIndexed { i, item -> decodeBlueprintGroupName(item, "$p[$i]") } } },
                locked = fields["locked"]?.let { ("$path.locked").let { p -> it.arrValues(p).mapIndexed { i, item -> decodeBlueprintItemKey(item, "$p[$i]") } } },
