        }
    }
}

/**
 * A closed motion preset (ADR-013): fade, rise (fade in from the block end), scale (fade and grow
 * from 96%), slide-start or slide-end (fade in from the inline start or end, mirrored right to
 * left). The runtime maps each to token keyframes; a blueprint never carries keyframes.
 */
enum class BlueprintMotionPreset(val wire: String) {
    FADE("fade"),
    RISE("rise"),
    SCALE("scale"),
    SLIDE_START("slide-start"),
    SLIDE_END("slide-end"),
    ;

    companion object {
        fun decode(json: JsonValue, path: String): BlueprintMotionPreset {
            val wire = json.str(path)
            return entries.firstOrNull { it.wire == wire }
                ?: throw SpecDecodeException(path, "unknown value \"$wire\"")
        }
    }
}

/**
 * A duration token step (@texuli/tokens motion durations), never milliseconds.
 */
enum class BlueprintMotionDuration(val wire: String) {
    FAST("fast"),
    BASE("base"),
    SLOW("slow"),
    ;

    companion object {
        fun decode(json: JsonValue, path: String): BlueprintMotionDuration {
            val wire = json.str(path)
            return entries.firstOrNull { it.wire == wire }
                ?: throw SpecDecodeException(path, "unknown value \"$wire\"")
        }
    }
}

/**
 * The offset between the entering children of this node, in token steps: none, fast or base. The
 * runtime caps the whole spread.
 */
enum class BlueprintMotionStagger(val wire: String) {
    NONE("none"),
    FAST("fast"),
    BASE("base"),
    ;

    companion object {
        fun decode(json: JsonValue, path: String): BlueprintMotionStagger {
            val wire = json.str(path)
            return entries.firstOrNull { it.wire == wire }
                ?: throw SpecDecodeException(path, "unknown value \"$wire\"")
        }
    }
}

/**
 * A motion ceiling (ADR-013): full, subtle (shorter, no travel or scale) or none (instant). The
 * host and the reader's reduced-motion preference can only lower it.
 */
enum class BlueprintMotionLevel(val wire: String) {
    FULL("full"),
    SUBTLE("subtle"),
    NONE("none"),
    ;

    companion object {
        fun decode(json: JsonValue, path: String): BlueprintMotionLevel {
            val wire = json.str(path)
            return entries.firstOrNull { it.wire == wire }
                ?: throw SpecDecodeException(path, "unknown value \"$wire\"")
        }
    }
}

/**
 * How a node moves (spec 0.6.0, ADR-012): named presets and token steps only. Nothing here is CSS,
 * a duration in milliseconds or code. The server paints the end state, and nothing plays on
 * hydration or under reduced motion.
 */
data class BlueprintNodeMotion(
    val enter: BlueprintMotionPreset? = null,
    val exit: BlueprintMotionPreset? = null,
    val layout: Boolean? = null,
    val stagger: BlueprintMotionStagger? = null,
    val duration: BlueprintMotionDuration? = null,
) {
    companion object {
        private val FIELDS = setOf("enter", "exit", "layout", "stagger", "duration")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintNodeMotion {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintNodeMotion(
                enter = fields["enter"]?.let { BlueprintMotionPreset.decode(it, "$path.enter") },
                exit = fields["exit"]?.let { BlueprintMotionPreset.decode(it, "$path.exit") },
                layout = fields["layout"]?.let { it.bool("$path.layout") },
                stagger = fields["stagger"]?.let { BlueprintMotionStagger.decode(it, "$path.stagger") },
                duration = fields["duration"]?.let { BlueprintMotionDuration.decode(it, "$path.duration") },
            )
        }
    }
}

/**
 * The blueprint's motion settings (spec 0.6.0): the level every node motion plays at.
 */
data class BlueprintEnvelopeMotion(
