/**
 * A Texuli document (spec 0.7.0, ADR-011): the format, version, metadata, page settings, block
 * list and annotations of `@texuli/document.` This contract checks the envelope of the document
 * only; the closed block vocabulary, text safety, the URL policy and the caps are checked by
 * `@texuli/document/schema` (schemas/document.schema.json) inside the runtime validator,
 * `@texuli/catalog`'s validateDraft, at the host's tier.
 */
data class BlueprintDocument(
    val format: String = "texuli-document",
    val formatVersion: Long = 1L,
    val meta: Map<String, JsonValue>,
    val page: Map<String, JsonValue>? = null,
    val blocks: List<Map<String, JsonValue>>,
    val annotations: Map<String, JsonValue>? = null,
) {
    companion object {
        private val FIELDS = setOf("format", "formatVersion", "meta", "page", "blocks", "annotations")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintDocument {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintDocument(
                format = fields.required("format", path).constant("texuli-document", "$path.format"),
                formatVersion = fields.required("formatVersion", path).constant(1L, "$path.formatVersion"),
                meta = ("$path.meta").let { p -> fields.required("meta", path).obj(p).mapValues { (k, item) -> item } },
                page = fields["page"]?.let { ("$path.page").let { p -> it.obj(p).mapValues { (k, item) -> item } } },
                blocks = ("$path.blocks").let { p -> fields.required("blocks", path).arrValues(p).mapIndexed { i, item -> ("$p[$i]").let { p -> item.obj(p).mapValues { (k, item) -> item } } } },
                annotations = fields["annotations"]?.let { ("$path.annotations").let { p -> it.obj(p).mapValues { (k, item) -> item } } },
            )
        }
    }
}

/**
 * One RFC 6902 operation on a document. Paths are RFC 6901 pointers into the document;
 * `@texuli/document/ops` refuses prototype paths and malformed escapes, applies the patch all or
 * none and validates the result.
 */
data class BlueprintDocumentPatchOperation(
    val op: BlueprintDocumentPatchOperationOp,
    val path: String,
    val from: String? = null,
    val value: JsonValue? = null,
) {
    companion object {
        private val FIELDS = setOf("op", "path", "from", "value")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintDocumentPatchOperation {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintDocumentPatchOperation(
                op = BlueprintDocumentPatchOperationOp.decode(fields.required("op", path), "$path.op"),
                path = fields.required("path", path).str("$path.path"),
                from = fields["from"]?.let { it.str("$path.from") },
                value = fields["value"]?.let { it },
            )
        }
    }
}

/**
 * A bounded RFC 6902 patch (ADR-011): at most 1,000 operations; test operations are encouraged.
 */
typealias BlueprintDocumentPatch = List<BlueprintDocumentPatchOperation>

fun decodeBlueprintDocumentPatch(json: JsonValue, path: String): BlueprintDocumentPatch =
    (path).let { p -> json.arrValues(p).mapIndexed { i, item -> BlueprintDocumentPatchOperation.decode(item, "$p[$i]") } }

/**
 * A Texuli canvas (spec 0.8.0, ADR-012): the format, version, metadata, grid, shapes and
