        fun decode(json: JsonValue, path: String = "\$"): BlueprintCanvas {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintCanvas(
                format = fields.required("format", path).constant("texuli-canvas", "$path.format"),
                formatVersion = fields.required("formatVersion", path).constant(1L, "$path.formatVersion"),
                meta = fields["meta"]?.let { ("$path.meta").let { p -> it.obj(p).mapValues { (k, item) -> item } } },
                grid = fields["grid"]?.let { it.double("$path.grid") },
                shapes = ("$path.shapes").let { p -> fields.required("shapes", path).arrValues(p).mapIndexed { i, item -> ("$p[$i]").let { p -> item.obj(p).mapValues { (k, item) -> item } } } },
                connectors = ("$path.connectors").let { p -> fields.required("connectors", path).arrValues(p).mapIndexed { i, item -> ("$p[$i]").let { p -> item.obj(p).mapValues { (k, item) -> item } } } },
            )
