/**
 * A data source the host registered (spec 0.8.0, ADR-015): an opaque name, never a URL. Checked
 * against the host's registry; with no registry a binding is refused.
 */
typealias BlueprintSourceName = String

fun decodeBlueprintSourceName(json: JsonValue, path: String): BlueprintSourceName =
    json.str(path)

/**
 * A field the source declares.
 */
typealias BlueprintSourceFieldName = String

fun decodeBlueprintSourceFieldName(json: JsonValue, path: String): BlueprintSourceFieldName =
    json.str(path)

/**
 * The `@texuli/data` grid filter model: a condition ({type: condition, field, operator, value}) or
 * an and/or group ({type: group, op, children}). At most 6 levels and 64 nodes. Which members each
 * type takes, the operators each field allows and the value types are checked by the validator
 * against the source's declaration.
 */
data class BlueprintSourceFilter(
    val type: BlueprintSourceFilterType,
    val field: BlueprintSourceFieldName? = null,
    val operator: BlueprintSourceFilterOperator? = null,
    val value: JsonValue? = null,
    val op: BlueprintSourceFilterOp? = null,
    val children: List<BlueprintSourceFilter>? = null,
) {
    companion object {
        private val FIELDS = setOf("type", "field", "operator", "value", "op", "children")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintSourceFilter {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintSourceFilter(
                type = BlueprintSourceFilterType.decode(fields.required("type", path), "$path.type"),
                field = fields["field"]?.let { decodeBlueprintSourceFieldName(it, "$path.field") },
                operator = fields["operator"]?.let { BlueprintSourceFilterOperator.decode(it, "$path.operator") },
                value = fields["value"]?.let { it },
                op = fields["op"]?.let { BlueprintSourceFilterOp.decode(it, "$path.op") },
                children = fields["children"]?.let { ("$path.children").let { p -> it.arrValues(p).mapIndexed { i, item -> BlueprintSourceFilter.decode(item, "$p[$i]") } } },
            )
        }
    }
}

/**
 * One sort key on a sortable field.
 */
data class BlueprintSourceSort(
    val field: BlueprintSourceFieldName,
    val direction: BlueprintSourceSortDirection? = null,
) {
    companion object {
        private val FIELDS = setOf("field", "direction")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintSourceSort {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintSourceSort(
                field = decodeBlueprintSourceFieldName(fields.required("field", path), "$path.field"),
                direction = fields["direction"]?.let { BlueprintSourceSortDirection.decode(it, "$path.direction") },
            )
        }
    }
}

/**
 * The closed query a data-source binding sends (ADR-015): projection, a filter, sort keys, search
 * text and a page size. The host adapter receives it validated and decides how to run it; Texuli
 * never builds URLs, SQL or code from it.
 */
data class BlueprintSourceQuery(
    val fields: List<BlueprintSourceFieldName>? = null,
    val filter: BlueprintSourceFilter? = null,
    val sort: List<BlueprintSourceSort>? = null,
    val search: String? = null,
    val pageSize: Long? = null,
) {
    companion object {
        private val FIELDS = setOf("fields", "filter", "sort", "search", "pageSize")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintSourceQuery {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintSourceQuery(
                fields = fields["fields"]?.let { ("$path.fields").let { p -> it.arrValues(p).mapIndexed { i, item -> decodeBlueprintSourceFieldName(item, "$p[$i]") } } },
                filter = fields["filter"]?.let { BlueprintSourceFilter.decode(it, "$path.filter") },
                sort = fields["sort"]?.let { ("$path.sort").let { p -> it.arrValues(p).mapIndexed { i, item -> BlueprintSourceSort.decode(item, "$p[$i]") } } },
                search = fields["search"]?.let { it.str("$path.search") },
                pageSize = fields["pageSize"]?.let { it.long("$path.pageSize") },
            )
        }
    }
}

/**
 * Reads a whole sourceable prop from a host data source (spec 0.8.0, ADR-015): {"$source": name,
 * "query": {...}, "map": {itemField: sourceField}}. The player loads the rows through the host's
 * registry; map renames source fields to the component's item fields (at most 16 entries).
 */
data class BlueprintSourceBinding(
    val source: BlueprintSourceName,
    val query: BlueprintSourceQuery? = null,
    val map: Map<String, BlueprintSourceFieldName>? = null,
) {
    companion object {
        private val FIELDS = setOf("\$source", "query", "map")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintSourceBinding {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintSourceBinding(
                source = decodeBlueprintSourceName(fields.required("\$source", path), "$path.\$source"),
                query = fields["query"]?.let { BlueprintSourceQuery.decode(it, "$path.query") },
                map = fields["map"]?.let { ("$path.map").let { p -> it.obj(p).mapValues { (k, item) -> decodeBlueprintSourceFieldName(item, "$p.$k") } } },
            )
        }
    }
}

/**
 * Envelope version 1 around one catalog tree (ADR-004, audit G13). Mirrors what
 * `@texuli/catalog/envelope` reads; a declared status, activation or tier is display data, never
 * authority. Spec 0.4.0 (ADR-008 + PLAN_008 deck encoding) adds an optional spec version, local
 * state and a flow; spec 0.6.0 (ADR-012, ADR-013) adds the closed motion vocabulary: a node motion
 * and the envelope motion level; spec 0.7.0 (ADR-011, ADR-012, ADR-014) adds an optional node key
 * (a stable instance id, unique in the tree), the document shape a `document` node carries and the
 * patchDocument edit op with its bounded RFC 6902 patch. Spec 0.8.0 (ADR-012, ADR-015) adds
 * data-source bindings: a sourceable prop may read rows from a source the host registered
 * ({"$source": name, "query": {...}}), with a closed query, and forms as data: the closed form
 * schema a `schema-form` node carries ($defs.formSchema) with conditions and cross-field rules in
 * the closed expression AST of `@texuli/core/expression` ($defs.expression). Spec 0.8.0 (ADR-012)
 * adds the canvas shape a `canvas` node carries ($defs.canvas). Planned minor additions: the
 * native profile and several roots.
 */
data class BlueprintEnvelope(
    val format: String = "texuli-blueprint",
    val version: Long = 1L,
    val id: String,
    val catalog: String,
    val status: BlueprintStatus,
    val createdAt: BlueprintTime,
    val updatedAt: BlueprintTime,
    val generator: BlueprintGenerator,
    val tier: BlueprintEmitTier? = null,
    val profile: BlueprintProfile? = null,
    val asOf: BlueprintTime? = null,
    val sources: List<BlueprintSource>? = null,
    val trigger: BlueprintTrigger? = null,
    val meetingRef: BlueprintMeetingRef? = null,
    val activatedBy: BlueprintActivation? = null,
    val provenance: List<BlueprintProvenanceEntry>? = null,
    val tree: BlueprintNode,
    val spec: BlueprintEnvelopeSpec? = null,
    val state: Map<String, BlueprintStateDeclaration>? = null,
    val flow: BlueprintFlow? = null,
    val motion: BlueprintEnvelopeMotion? = null,
) {
    companion object {
        private val FIELDS = setOf("format", "version", "id", "catalog", "status", "createdAt", "updatedAt", "generator", "tier", "profile", "asOf", "sources", "trigger", "meetingRef", "activatedBy", "provenance", "tree", "spec", "state", "flow", "motion")

        fun decode(json: JsonValue, path: String = "\$"): BlueprintEnvelope {
            val fields = json.obj(path)
            fields.requireOnly(FIELDS, path)
            return BlueprintEnvelope(
                format = fields.required("format", path).constant("texuli-blueprint", "$path.format"),
                version = fields.required("version", path).constant(1L, "$path.version"),
                id = fields.required("id", path).str("$path.id"),
                catalog = fields.required("catalog", path).str("$path.catalog"),
                status = BlueprintStatus.decode(fields.required("status", path), "$path.status"),
                createdAt = decodeBlueprintTime(fields.required("createdAt", path), "$path.createdAt"),
                updatedAt = decodeBlueprintTime(fields.required("updatedAt", path), "$path.updatedAt"),
                generator = BlueprintGenerator.decode(fields.required("generator", path), "$path.generator"),
                tier = fields["tier"]?.let { BlueprintEmitTier.decode(it, "$path.tier") },
                profile = fields["profile"]?.let { BlueprintProfile.decode(it, "$path.profile") },
                asOf = fields["asOf"]?.let { decodeBlueprintTime(it, "$path.asOf") },
                sources = fields["sources"]?.let { ("$path.sources").let { p -> it.arrValues(p).mapIndexed { i, item -> BlueprintSource.decode(item, "$p[$i]") } } },
                trigger = fields["trigger"]?.let { BlueprintTrigger.decode(it, "$path.trigger") },
                meetingRef = fields["meetingRef"]?.let { BlueprintMeetingRef.decode(it, "$path.meetingRef") },
                activatedBy = fields["activatedBy"]?.let { BlueprintActivation.decode(it, "$path.activatedBy") },
                provenance = fields["provenance"]?.let { ("$path.provenance").let { p -> it.arrValues(p).mapIndexed { i, item -> BlueprintProvenanceEntry.decode(item, "$p[$i]") } } },
                tree = BlueprintNode.decode(fields.required("tree", path), "$path.tree"),
                spec = fields["spec"]?.let { BlueprintEnvelopeSpec.decode(it, "$path.spec") },
                state = fields["state"]?.let { ("$path.state").let { p -> it.obj(p).mapValues { (k, item) -> BlueprintStateDeclaration.decode(item, "$p.$k") } } },
                flow = fields["flow"]?.let { BlueprintFlow.decode(it, "$path.flow") },
                motion = fields["motion"]?.let { BlueprintEnvelopeMotion.decode(it, "$path.motion") },
            )
        }
    }
}

